import { computed, ref } from 'vue'

/**
 * Dua bahasa: Indonesia (id) dan Inggris (en). Pilihan disimpan di perangkat (orcax_lang).
 * - t('kunci', { param })  : teks antarmuka.
 * - ts('teks server')      : teks yang dikirim backend (status, peringatan, pesan galat) diterjemahkan
 *                            bila bahasa Inggris dipilih; teks yang tidak dikenal ditampilkan apa adanya.
 */
const KEY = 'orcax_lang'
const read = () => { try { const v = localStorage.getItem(KEY); return v === 'en' || v === 'id' ? v : 'id' } catch { return 'id' } }

export const lang = ref(read())
export const isEn = computed(() => lang.value === 'en')
/** Locale untuk format angka & tanggal. */
export const locale = computed(() => (lang.value === 'en' ? 'en-GB' : 'id-ID'))
export const numLocale = computed(() => (lang.value === 'en' ? 'en-US' : 'id-ID'))

export function setLang(l) {
  lang.value = l === 'en' ? 'en' : 'id'
  try { localStorage.setItem(KEY, lang.value) } catch { /* abaikan */ }
  document.documentElement.lang = lang.value
}
document.documentElement.lang = lang.value

