export function t(key, params) {
  const dict = lang.value === 'en' ? en : id
  let s = dict[key] ?? id[key] ?? key
  if (params) s = s.replace(/\{(\w+)\}/g, (_, k) => (params[k] ?? ''))
  return s
}

