export function ts(s) {
  if (lang.value !== 'en' || s == null || s === '') return s
  if (serverEn[s]) return serverEn[s]
  let m
  if ((m = /^Verifikasi (.+)$/.exec(s))) return `Verification ${m[1]}`
  if ((m = /^Disetujui (.+)$/.exec(s))) return `Approved ${m[1]}`
  if ((m = /^Ditolak (.+)$/.exec(s))) return `Rejected ${m[1]}`
  if ((m = /^Harga (Tier .+)$/.exec(s))) return `${m[1]} Price`
  return s
}
